    /// <summary>
    /// Modified field
    /// </summary>
    /// <param name = "_fieldId">fieldId</param>
    public void modifiedField(FieldId _fieldId)
    {
        super(_fieldId);

        switch (_fieldId)
        {
            case fieldNum(METPalletRoundingPolicyLine, ItemCode):
                this.ItemId = METConstants::emptyString;
                this.Category = 0;
                break;

            case fieldNum(METPalletRoundingPolicyLine, AccountCode):
                this.AccountRelation = '';
                break;

            // CB223_PalletRounding RuleType no longer required
            /*case fieldNum(METPalletRoundingPolicyLine, RuleType):
                if (this.RuleType == METPalletRoundingPolicyRuleType::Exclude &&
                    this.ItemCode != TableGroupAll::Table)
                {
                    this.ItemCode       = TableGroupAll::Table;
                    this.ItemRelation   = '';                                      
                }
                break;*/
        }
    }

    /// <summary>
    /// Finds the specified record in the <c>METPalletRoundingPolicyLine</c> table.
    /// </summary>
    /// <param name="_recId">
    /// Record Id.
    /// </param>
    /// <param name="_forUpdate">
    /// A Boolean value that indicates whether to read the record for update; optional.
    /// </param>
    /// <returns>
    /// A <c>METPalletRoundingPolicyLine</c> record if found; otherwise, an empty record.
    /// </returns>
    static  METPalletRoundingPolicyLine findRecId(RecId      _recId,
                                                  boolean    _forUpdate = false)
    {
        METPalletRoundingPolicyLine policyLine;

        policyLine.selectForUpdate(_forUpdate);

        select firstonly policyLine
            where policyLine.RecId == _recId;

        return policyLine;
    }

/// <summary>
/// Clear the cacheKey when pallet rounding policy line record is updated (Percentage)
/// </summary>
public void update()
{        
    super();
    if (this.METPalletRoundingPolicyHeader().Active)
    {
        METPalletRoundingPolicyCacheKey::removePalletRoundingPolicyLineCache(this);
    }
}

/// <summary>
/// Clear the cacheKey when pallet rounding policy line record is deleted
/// </summary>
public void delete()
{
    super();
    if (this.METPalletRoundingPolicyHeader().Active)
    {
        METPalletRoundingPolicyCacheKey::removePalletRoundingPolicyLineCache(this);
    }
}

/// <summary>
/// Clear the cacheKey when pallet rounding policy line record is insert
/// to manage scenario where cache saved no pallet rounding policy for that combination
/// </summary>
public void insert()
{
    super();
    if (this.METPalletRoundingPolicyHeader().Active)
    {
        METPalletRoundingPolicyCacheKey::removePalletRoundingPolicyLineCache(this);
    }
}

/// <summary>
/// Retrieve the pallet rounding policy header from line
/// </summary>
/// <param name = "_forUpdate">select for update</param>
/// <returns><c>METPalletRoundingPolicyHeader</c> record</returns>
public METPalletRoundingPolicyHeader METPalletRoundingPolicyHeader(boolean _forUpdate = false)
{
    return METPalletRoundingPolicyHeader::find(this.InventSiteId, _forUpdate);
}

    /// <summary>
    /// Record validation
    /// </summary>
    /// <returns>True if successful; otherzise, false.</returns>
    public boolean validateWrite()
    {
        boolean ret;
    
        ret = super();
    
        if (this.AccountCode == METCustomerGroupAll::GroupId ||
            this.AccountCode == METCustomerGroupAll::Table)
        {
            if (!this.AccountRelation)
            {
                ret = checkFailed(strFmt("@MET:SubFieldMustBeSpecified",
                    fieldPName(METPalletRoundingPolicyLine, AccountRelation)));
            }
        }

        if (this.ItemCode == METItemTableGroup::Table && !this.ItemId)
        {
            ret = checkFailed(strFmt("@MET:SubFieldMustBeSpecified",
                    fieldPName(METPalletRoundingPolicyLine, ItemId)));
        }

        if (this.ItemCode == METItemTableGroup::GroupId && !this.Category)
        {
            ret = checkFailed(strFmt("@MET:SubFieldMustBeSpecified",
                    fieldPName(METPalletRoundingPolicyLine, Category)));
        }

        return ret;
    }
